def count_case_insensitive_occurrences(s, sub):
    if not sub:
        return 0
    s_l, sub_l = s.lower(), sub.lower()
    count = 0
    start = 0
    while True:
        idx = s_l.find(sub_l, start)
        if idx == -1:
            break
        count += 1
        start = idx + len(sub_l)
    return count

def interleave_two_sorted_lists(a, b):
    i = j = 0
    res = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            res.append(a[i])
            i += 1
        else:
            res.append(b[j])
            j += 1
    res.extend(a[i:])
    res.extend(b[j:])
    return res

